/// <summary>
/// adds report design to print management
/// </summary>
/// <param name = "_docType">Type of report run</param>
/// <param name = "_result">adds report design to print management</param>
[SubscribesTo(classStr(PrintMgmtDocType), delegateStr(PrintMgmtDocType, getDefaultReportFormatDelegate))]
public static void PrintMgmtDocType_getDefaultReportFormatDelegate(PrintMgmtDocumentType _docType, EventHandlerResult _result)
{
    switch (_docType)
    {
        case PrintMgmtDocumentType::VendPaymAdvice:
            _result.result(ssrsReportStr(METBankPaymAdviceVendV2, Report));
            break;
    }
}
